// 1) Kaynakları al
const genelResp = $('genel bilgiler1').first().json;
const detayResp = $('portföy dağılımı1').first().json;

const genelList = genelResp?.resultList ?? genelResp?.data?.resultList ?? [];
const detayList = detayResp?.resultList ?? detayResp?.data?.resultList ?? [];

// 2) Tarih formatlayıcı 
function toDDMMYYYY(iso) {
  if (!iso) return null;
  const s = String(iso).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return `${m[3]}.${m[2]}.${m[1]}`;
  return s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/) ? s : null;
}

// 3) HIZLANDIRICI: Detay listesini bir map haline getir
const detayMap = {};
if (Array.isArray(detayList)) {
  for (const item of detayList) {
    const key = (item?.fonKodu ?? item?.FONKODU ?? '').toString().trim();
    if (key) {
      detayMap[key] = item;
    }
  }
}

// 4) Liste kontrolü
if (!Array.isArray(genelList) || genelList.length === 0) {
  return [{ json: { _skip: true, reason: 'genelList boş' } }];
}

// 5) Birleştirme 
return genelList.map(genel => {
  const code = (genel?.fonKodu ?? genel?.FONKODU ?? '').toString().trim();

  // .find() yerine doğrudan Map'ten çekilir
  const detay = detayMap[code] || {};

  const sql_tarih = toDDMMYYYY(genel?.tarih ?? detay?.tarih);

  return {
    json: {
      ...genel,
      ...detay,
      sql_tarih,
      fonKodu: code
    }
  };
});
